with lines as (select id, customer_id, coupon_codes, inline(items) from carts), exploded as (select product_id, qty, explode(coupon_codes) as element from lines), valid as (select *, cast(product_id as double) as product_id_num from exploded where element is not null), cleaned as (select *, cast(qty as double) as qty_str from valid where qty < 4), with_windows as (select product_id, qty_str, rank() over w_recent as qty_str_rank, max(qty) over (partition by element) as element_max_qty, percent_rank() over w_ordered as product_id_percent_rank from cleaned window w_recent as (partition by element order by qty_str desc nulls last), w_ordered as (order by product_id desc)), daily as (select case when product_id >= 10 then 'PREMIUM' else 'STANDARD' end as product_id_tier, round(avg(qty_str_rank), 2) as avg_qty_str_rank, round(avg(product_id), 2) as avg_product_id, approx_percentile(product_id_percent_rank, 0.5) as product_id_percent_rank_p50 from with_windows group by case when product_id >= 10 then 'PREMIUM' else 'STANDARD' end) select product_id_tier, avg_qty_str_rank, avg_product_id, product_id_percent_rank_p50 from daily order by avg_qty_str_rank desc nulls first
